const data    = $('Code in JavaScript | Fetch Code Node').first().json;
const ruleset = $('Edit Fields | USD Ruleset').first().json.ruleset;
const eco     = $('Code | Process Eco Data').first().json;

// Format surprise scores for prompt
const surpriseText = eco.surprises.length > 0
  ? eco.surprises.map(s =>
      `  • ${s.event} (${s.date}): actual ${s.actual} vs estimate ${s.estimate} → ${s.direction} (${s.surprise > 0 ? '+' : ''}${s.surprise}σ)`
    ).join('\n')
  : '  • No tier-1 releases in the past 7 days';

// Format upcoming calendar for prompt
const calendarText = eco.calendar.filter(e => e.impact === 'high').length > 0
  ? eco.calendar
      .filter(e => e.impact === 'high')
      .map(e => `  • ${e.event} @ ${e.time} UTC${e.estimate !== null ? ` — consensus: ${e.estimate}` : ''}`)
      .join('\n')
  : '  • No high-impact US events scheduled this week';

const body = {
  model: "claude-sonnet-4-6",
  max_tokens: 8000,
  system: ruleset,
  messages: [{
    role: "user",
    content: `Today's macro data as of ${data.timestamp}:

${JSON.stringify(data, null, 2)}

RECENT TIER-1 DATA SURPRISES (last 7 days):
${surpriseText}

UPCOMING HIGH-IMPACT US EVENTS (next 7 days):
${calendarText}

Please provide your full USD directional diagnosis following the output template in Section 14 of your ruleset.`
  }]
};

return [{ json: body }];

// FRED data
const us2y    = parseFloat($('HTTP Request | US 2Y Treasury Yield - FRED API').first().json.observations[0].value);
const us10y   = parseFloat($('HTTP Request | US 10Y Treasury Yield - FRED Api').first().json.observations[0].value);
const tips10y = parseFloat($('HTTP Request | TIPS 10Y Real Yield - FRED Api').first().json.observations[0].value);
const de10y   = parseFloat($('HTTP Request | Germany 10Y Proxy - FRED Api').first().json.observations[0].value);
const uk10y   = parseFloat($('HTTP Request | UK 10Y Proxy - FRED api').first().json.observations[0].value);
const jp10y   = parseFloat($('HTTP Request | Japan 10Y Proxy - FRED API').first().json.observations[0].value);
const vix     = parseFloat($('HTTP Request | VIX - FRED Api').first().json.observations[0].value);
const dxy     = parseFloat($('HTTP Request | DXY - FRED Dollar Index - FRED API').first().json.observations[0].value);
const wti     = parseFloat($('HTTP Request | WTI Oil - FRED Api').first().json.observations[0].value);
const brent   = parseFloat($('HTTP Request | Brent Oil - FRED Api').first().json.observations[0].value);
const eurUsd  = parseFloat($('HTTP Request | EURUSD - FRED API').first().json.observations[0].value);

// Coinbase data
const gold   = parseFloat($('HTTP Request | Gold - Coinbase').first().json.data.amount);
const btc    = parseFloat($('HTTP Request | BTC - Coinbase').first().json.data.amount);
const jpyRaw = parseFloat($('HTTP Request | USD/JPY - Coinbase').first().json.data.amount);
const gbpUsd = parseFloat($('HTTP Request | GBP/USD - Coinbase').first().json.data.amount);
const cadRaw = parseFloat($('HTTP Request | USD/CAD - Coinbase').first().json.data.amount);
const audUsd = parseFloat($('HTTP Request | AUD/USD - Coinbase').first().json.data.amount);

// Convert to standard FX conventions
const usdJpy = 1 / jpyRaw;
const usdCad = 1 / cadRaw;

// Compute spreads
const usDeSpread     = us2y - de10y;
const usUkSpread     = us10y - uk10y;
const usJpSpread     = us10y - jp10y;
const brentWtiSpread = brent - wti;

return [{
  json: {
    timestamp: new Date().toISOString(),
    rates:   { us2y, us10y, tips10y, de10y, uk10y, jp10y, vix, dxy, wti, brent },
    prices:  { eurUsd, gold, btc, gbpUsd, audUsd, usdJpy, usdCad },
    spreads: { usDeSpread, usUkSpread, usJpSpread, brentWtiSpread }
  }
}];

const response = $input.first().json;
const diagnosisText = response.content[0].text;

return [{
  json: {
    diagnosis: diagnosisText,
    timestamp: new Date().toISOString()
  }
}];

const diagnosis = $input.first().json.diagnosis;

const body = {
  model: "claude-sonnet-4-6",
  max_tokens: 4000,
  system: `You are a structured data extractor. Given a USD macro diagnosis, extract trading calls in strict JSON format. Output ONLY valid JSON, no other text.`,
  messages: [{
    role: "user",
    content: `From this diagnosis, extract trading calls for all 9 markets across 3 timeframes (24h, 72h, weekly).

Markets: EUR/USD, USD/JPY, GBP/USD, USD/CAD, AUD/USD, NQ, BTC/USD, XAU/USD, WTI Oil

Return a JSON array of 27 objects, each with:
- market (string)
- timeframe (string: "24h", "72h", or "weekly")
- direction (string: "LONG", "SHORT", or "NO TRADE")
- conviction (number: 1-5)
- rationale (string: one sentence)

DIAGNOSIS:
${diagnosis}`
  }]
};

return [{ json: body }];

const response = $input.first().json;
const rawText = response.content[0].text;

const cleaned = rawText.replace(/```json\n?/g, '').replace(/```/g, '').trim();
const calls = JSON.parse(cleaned);

const timestamp = new Date().toISOString();

// Calculate expiry based on NY close (22:00 London = 17:00 NY)
function getExpiry(timeframe) {
  const now = new Date();
  const nyCloseHourUTC = 21;

  const close = new Date(now);
  close.setUTCHours(nyCloseHourUTC, 0, 0, 0);

  if (now >= close) close.setUTCDate(close.getUTCDate() + 1);

  if (timeframe === '24h') {
    const day = close.getUTCDay();
    if (day === 6) close.setUTCDate(close.getUTCDate() + 2);
    if (day === 0) close.setUTCDate(close.getUTCDate() + 1);
    return close.toISOString();
  }

  if (timeframe === '72h') {
    let added = 0;
    while (added < 3) {
      close.setUTCDate(close.getUTCDate() + 1);
      const d = close.getUTCDay();
      if (d !== 0 && d !== 6) added++;
    }
    return close.toISOString();
  }

  if (timeframe === 'weekly') {
    const daysUntilFriday = (5 - close.getUTCDay() + 7) % 7 || 7;
    close.setUTCDate(close.getUTCDate() + daysUntilFriday);
    return close.toISOString();
  }

  return null;
}

// Entry prices passed through from the fetch aggregator
const prices = $('Code in JavaScript | Fetch Code Node').first().json.prices;
const rates  = $('Code in JavaScript | Fetch Code Node').first().json.rates;

const priceMap = {
  'EUR/USD':  prices.gbpUsd   ? null : null,  // placeholder — filled below
  'USD/JPY':  prices.usdJpy,
  'GBP/USD':  prices.gbpUsd,
  'USD/CAD':  prices.usdCad,
  'AUD/USD':  prices.audUsd,
  'NQ':       null,
  'BTC/USD':  prices.btc,
  'XAU/USD':  prices.gold,
  'WTI Oil':  rates.wti
};

// EUR/USD isn't in the fetch yet — will be null until we add it
priceMap['EUR/USD'] = prices.eurUsd || null;

const callsWithTimestamp = calls.map(call => ({
  ...call,
  timestamp,
  status:      'OPEN',
  source:      'donnelly',
  entry_price: priceMap[call.market] || null,
  expiry_at:   getExpiry(call.timeframe)
}));

return callsWithTimestamp.map(call => ({ json: call }));

