const diagnosisText = response.content[0].text;

return [{
  json: {
    diagnosis: diagnosisText,
    timestamp: new Date().toISOString()
  }
}];

const diagnosis = $input.first().json.diagnosis;

const body = {
  model: "claude-sonnet-4-6",
  max_tokens: 4000,
  system: `You are a structured data extractor. Given a USD macro O Layer diagnosis, extract trading calls in strict JSON format. Output ONLY valid JSON, no other text.

The diagnosis contains 27 trading calls in this format:
  [MARKET] [TIMEFRAME] | Donnelly: [direction] ★[N] | O Layer: [modifier] | Final: [direction] ★[N]

You must extract direction and conviction from the FINAL field only. The Donnelly and O Layer fields are context — they are not the output. The Final field is the authoritative call.`,
  messages: [{
    role: "user",
    content: `From this O Layer diagnosis, extract the 27 Final trading calls for all 9 markets across 3 timeframes (24h, 72h, weekly).

Markets: EUR/USD, USD/JPY, GBP/USD, USD/CAD, AUD/USD, NQ, BTC/USD, XAU/USD, WTI Oil

Return a JSON array of 27 objects, each with:
- market (string)
- timeframe (string: "24h", "72h", or "weekly")
- direction (string: "LONG", "SHORT", or "NO TRADE") — from the Final field only
- conviction (number: 1-5) — star count from the Final field only
- rationale (string: one sentence summarising the Donnelly basis plus any O Layer modifier applied)

DIAGNOSIS:
${diagnosis}`
  }]
};

return [{ json: body }];

const response = $input.first().json;
const rawText = response.content[0].text;

const cleaned = rawText.replace(/```json\n?/g, '').replace(/```/g, '').trim();
const calls = JSON.parse(cleaned);

const timestamp = new Date().toISOString();

function getExpiry(timeframe) {
  const now = new Date();
  const nyCloseHourUTC = 21;

  const close = new Date(now);
  close.setUTCHours(nyCloseHourUTC, 0, 0, 0);

  if (now >= close) close.setUTCDate(close.getUTCDate() + 1);

  if (timeframe === '24h') {
    const day = close.getUTCDay();
    if (day === 6) close.setUTCDate(close.getUTCDate() + 2);
    if (day === 0) close.setUTCDate(close.getUTCDate() + 1);
    return close.toISOString();
  }

  if (timeframe === '72h') {
    let added = 0;
    while (added < 3) {
      close.setUTCDate(close.getUTCDate() + 1);
      const d = close.getUTCDay();
      if (d !== 0 && d !== 6) added++;
    }
    return close.toISOString();
  }

  if (timeframe === 'weekly') {
    const daysUntilFriday = (5 - close.getUTCDay() + 7) % 7 || 7;
    close.setUTCDate(close.getUTCDate() + daysUntilFriday);
    return close.toISOString();
  }

  return null;
}

const prices = $('Code in JavaScript | Fetch Code Node').first().json.prices;
const rates  = $('Code in JavaScript | Fetch Code Node').first().json.rates;

const priceMap = {
  'EUR/USD':  prices.eurUsd || null,
  'USD/JPY':  prices.usdJpy,
  'GBP/USD':  prices.gbpUsd,
  'USD/CAD':  prices.usdCad,
  'AUD/USD':  prices.audUsd,
  'NQ':       null,
  'BTC/USD':  prices.btc,
  'XAU/USD':  prices.gold,
  'WTI Oil':  rates.wti
};

const callsWithTimestamp = calls.map(call => ({
  ...call,
  timestamp,
  status:      'OPEN',
  source:      'omors',
  entry_price: priceMap[call.market] || null,
  expiry_at:   getExpiry(call.timeframe)
}));

return callsWithTimestamp.map(call => ({ json: call }));

const donnellyCalls = $('Code in JavaScript | Parse Calls').all().map(i => i.json);
const oLayerCalls = $('Code in JavaScript | Parse O Layer Calls').all().map(i => i.json);

const comparison = donnellyCalls.map(d => {
  const o = oLayerCalls.find(c => c.market === d.market && c.timeframe === d.timeframe);
  const agree = o && d.direction === o.direction;

  return {
    market:              d.market,
    timeframe:           d.timeframe,
    donnelly_direction:  d.direction,
    donnelly_conviction: d.conviction,
    omors_direction:     o ? o.direction  : 'N/A',
    omors_conviction:    o ? o.conviction : null,
    agreement:           agree ? 'AGREE' : 'CONFLICT',
    conviction_delta:    o ? Math.abs(d.conviction - o.conviction) : null
  };
});

const agreements = comparison.filter(c => c.agreement === 'AGREE').length;
const conflicts = comparison.filter(c => c.agreement === 'CONFLICT').length;

return [{
  json: {
    timestamp:       new Date().toISOString(),
    agreements,
    conflicts,
    agreement_rate:  Math.round((agreements / comparison.length) * 100),
    comparison_json: JSON.stringify(comparison)
  }
}];

const recent   = $('HTTP Request | Eco Calendar Recent - Finnhub').first().json.economicCalendar;
const upcoming = $('HTTP Request | Eco Calendar Upcoming - Finnhub').first().json.economicCalendar;

// Tier-1 US indicators with sigma values for surprise normalisation
const TIER1 = {
  'Non Farm Payrolls':          { key: 'NFP',           sigma: 80 },
  'Average Hourly Earnings MoM':{ key: 'AHE_MOM',       sigma: 0.1 },
  'Unemployment Rate':          { key: 'UNEMPLOYMENT',  sigma: 0.15 },
  'Core Inflation Rate MoM':    { key: 'CORE_CPI_MOM',  sigma: 0.1 },
  'Inflation Rate MoM':         { key: 'CPI_MOM',       sigma: 0.15 },
  'ISM Manufacturing PMI':      { key: 'ISM_MFG',       sigma: 2.5 },
  'ISM Services PMI':           { key: 'ISM_SVCS',      sigma: 2.5 },
  'GDP Growth Rate QoQ Adv':    { key: 'GDP_ADV',       sigma: 0.5 },
  'ADP Employment Change':      { key: 'ADP',           sigma: 50 },
  'Initial Jobless Claims':     { key: 'JOBLESS_CLAIMS',sigma: 15 },
  'JOLTs Job Openings':         { key: 'JOLTS',         sigma: 0.3 }
};

// Filter recent US high/medium impact events with actuals
const recentUS = (recent || []).filter(e =>
  e.country === 'US' &&
  ['high','medium'].includes(e.impact) &&
  e.actual !== null
);

// Filter upcoming US high/medium impact events without actuals
const upcomingUS = (upcoming || []).filter(e =>
  e.country === 'US' &&
  ['high','medium'].includes(e.impact) &&
  e.actual === null
);

// Compute surprise scores for tier-1 recent prints
const surprises = [];
for (const event of recentUS) {
  const tier1 = TIER1[event.event];
  if (!tier1) continue;
  if (event.actual === null || event.estimate === null) continue;
  const surprise = (event.actual - event.estimate) / tier1.sigma;
  surprises.push({
    key:       tier1.key,
    event:     event.event,
    date:      event.time.split(' ')[0],
    actual:    event.actual,
    estimate:  event.estimate,
    surprise:  Math.round(surprise * 100) / 100,
    direction: surprise > 0 ? 'BEAT' : surprise < 0 ? 'MISS' : 'IN LINE'
  });
}

// Format upcoming calendar
const calendar = upcomingUS.map(e => ({
  event:    e.event,
  time:     e.time,
  estimate: e.estimate,
  impact:   e.impact
}));

// Format recent all US high/medium events (not just tier-1) for prompt context
const recentSummary = recentUS.slice(-20).map(e => ({
  event:    e.event,
  time:     e.time.split(' ')[0],
  actual:   e.actual,
  estimate: e.estimate,
  prev:     e.prev,
  impact:   e.impact
}));

return [{
  json: {
    surprises,
    calendar,
    recentSummary
  }
}];

const aggregated = $('Code in JavaScript | Fetch Code Node').first().json;
const diagnosis  = $('HTTP Request | Diagnosis - Claude API').first().json;
const extracted  = $('HTTP Request | Extract Calls - Claude API').first().json;
const logged     = $('HTTP Request | Log to Supabase').first().json;

const errors = [];

// Check for null data feeds
const rates  = aggregated.rates  || {};
const prices = aggregated.prices || {};

const feedChecks = {
  us2y:   rates.us2y,
  us10y:  rates.us10y,
  tips10y: rates.tips10y,
  de10y:  rates.de10y,
  vix:    rates.vix,
  dxy:    rates.dxy,
  wti:    rates.wti,
  brent:  rates.brent,
  gold:   prices.gold,
  btc:    prices.btc,
  gbpUsd: prices.gbpUsd,
  audUsd: prices.audUsd,
  usdJpy: prices.usdJpy,
  usdCad: prices.usdCad,
};

for (const [key, val] of Object.entries(feedChecks)) {
  if (val === null || val === undefined || isNaN(val)) {
    errors.push(`Data feed failed: ${key}`);
  }
}

// Check Claude diagnosis
if (!diagnosis?.content?.[0]?.text) {
  errors.push('Claude diagnosis API call failed');
}

// Check Claude extraction
if (!extracted?.content?.[0]?.text) {
  errors.push('Claude extraction API call failed');
}

// Check Supabase log
if (logged?.error || logged?.code) {
  errors.push(`Supabase log failed: ${logged.message || logged.error}`);
}

const hasErrors = errors.length > 0;

return [{
  json: {
    hasErrors,
    errors,
    errorCount: errors.length,
    message: hasErrors
      ? `USD Agent completed with ${errors.length} error(s):\n\n${errors.map(e => `• ${e}`).join('\n')}`
      : 'USD Agent completed cleanly — all feeds healthy'
  }
}];
